using System;
using System.Linq;

namespace CliFx.Completion;

/// <summary>
/// Shell integration scripts that forward completion requests to the application.
/// </summary>
/// <remarks>
/// Every script does the same thing: collect the text typed up to the cursor, run
/// "executable [suggest] text", and turn the tab-separated output
/// (value, display text, description) into whatever the shell expects.
/// </remarks>
internal static class CompletionScripts
{
    private const string PowerShell = """
        # PowerShell completion for __NAME__ (generated by CliFx)
        #
        # Enable for the current session:
        #   __NAME__ '[completion]' powershell | Out-String | Invoke-Expression
        # Enable permanently by adding the line above to your $PROFILE.
        Register-ArgumentCompleter -Native -CommandName @('__NAME__', '__NAME__.exe') -ScriptBlock {
            param($wordToComplete, $commandAst, $cursorPosition)

            # The AST drops trailing whitespace, so restore everything that was typed up to the cursor
            $length = $cursorPosition - $commandAst.Extent.StartOffset
            $line = $commandAst.ToString().PadRight($length, ' ').Substring(0, $length)

            # Windows PowerShell does not escape embedded quotes when calling native programs
            if ($null -eq $PSNativeCommandArgumentPassing -or $PSNativeCommandArgumentPassing -eq 'Legacy') {
                $line = $line.Replace('"', '\"')
            }

            $previousEncoding = [Console]::OutputEncoding
            try {
                [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
                $output = & $commandAst.CommandElements[0].Value '[suggest]' $line 2>$null
            } catch {
                return
            } finally {
                [Console]::OutputEncoding = $previousEncoding
            }

            foreach ($entry in $output) {
                if ([string]::IsNullOrEmpty($entry)) { continue }

                $fields = $entry -split "`t", 3
                $value = $fields[0]
                $display = if ($fields.Count -gt 1 -and $fields[1]) { $fields[1] } else { $value }
                $description = if ($fields.Count -gt 2 -and $fields[2]) { $fields[2] } else { $display }
                $text = if ($value -match '\s') { "'" + $value.Replace("'", "''") + "'" } else { $value }

                [System.Management.Automation.CompletionResult]::new($text, $display, 'ParameterValue', $description)
            }
        }
        """;

    private const string Bash = """
        # bash completion for __NAME__ (generated by CliFx)
        #
        # Enable for the current session:
        #   source <(__NAME__ '[completion]' bash)
        # Enable permanently by adding the line above to ~/.bashrc.
        __FUNCTION__() {
            local line="${COMP_LINE:0:COMP_POINT}"
            local value

            COMPREPLY=()
            while IFS=$'\t' read -r value _; do
                [[ -n "$value" ]] && COMPREPLY+=("$(printf '%q' "$value")")
            done < <("${COMP_WORDS[0]}" '[suggest]' "$line" 2>/dev/null)
        }

        complete -F __FUNCTION__ __NAME__
        """;

    private const string Zsh = """
        #compdef __NAME__
        # zsh completion for __NAME__ (generated by CliFx)
        #
        # Enable for the current session (requires compinit):
        #   source <(__NAME__ '[completion]' zsh)
        # Enable permanently by adding the line above to ~/.zshrc, after compinit.
        __FUNCTION__() {
            local line="${(j: :)words[1,CURRENT-1]} ${PREFIX}"
            local -a lines items fields
            local entry text
            local -i unrelated=0

            lines=("${(@f)$("${words[1]}" '[suggest]' "$line" 2>/dev/null)}")
            for entry in "${lines[@]}"; do
                [[ -z "$entry" ]] && continue
                fields=("${(@ps:\t:)entry}")

                # Only the description is shown next to the value, so display text goes there too
                text="${fields[3]}"
                [[ "${fields[2]}" != "${fields[1]}" ]] && text="${fields[2]}${text:+ - $text}"

                # _describe expects "value:description", with colons in the value escaped
                items+=("${fields[1]//:/\\:}${text:+:$text}")

                [[ "${fields[1]:l}" == "${PREFIX:l}"* ]] || unrelated=1
            done

            # Values that don't start with what has been typed (e.g. IDs found by name) would replace
            # it with their common prefix, so use menu completion to keep the typed text until a choice is made
            (( unrelated )) && compstate[insert]=menu

            # -U: suggestions are not necessarily prefixed by what has been typed
            (( ${#items} )) && _describe -t '__NAME__-suggestions' '__NAME__' items -U
        }

        compdef __FUNCTION__ __NAME__
        """;

    public static bool TryGet(string shell, string executableName, out string script)
    {
        var template = shell.ToLowerInvariant() switch
        {
            "powershell" or "pwsh" => PowerShell,
            "bash" => Bash,
            "zsh" => Zsh,
            _ => null,
        };

        if (template is null)
        {
            script = "";
            return false;
        }

        var name = executableName.EndsWith(".exe", StringComparison.OrdinalIgnoreCase)
            ? executableName[..^4]
            : executableName;

        var function =
            "_"
            + new string(name.Select(c => char.IsLetterOrDigit(c) ? c : '_').ToArray())
            + "_complete";

        // Scripts must be LF-terminated, even if this file was checked out with CRLF
        script = template
            .Replace("\r\n", "\n")
            .Replace("__FUNCTION__", function)
            .Replace("__NAME__", name);
        return true;
    }
}
